{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Practical wellbeing for busy lives</title>
  <meta name="description" content="Events and short series to build reliable routines and habits — outcomes, frameworks, and simple practices." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body>
  <header class="site-header">
    <div class="container header-row">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav" role="navigation">
        <ul>
          <li><a href="/">Home</a></li>
          <li><a href="about.html">Why</a></li>
          <li><a href="services.html">Offerings</a></li>
          <li><a href="programs.html">Series</a></li>
          <li><a href="pricing.html">Rates</a></li>
          <li><a href="testimonials.html">Voices</a></li>
          <li><a href="book.html">Book</a></li>
          <li><a href="contact.html">Reach</a></li>
        </ul>
      </nav>
      <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      <button class="nav-toggle" aria-label="Toggle navigation">☰</button>
    </div>
    <svg class="pattern" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 60" preserveAspectRatio="none">
      <defs>
        <pattern id="p" width="10" height="10" patternUnits="userSpaceOnUse">
          <rect width="4" height="4" fill="#f3f7f4" />
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#p)" />
    </svg>
  </header>

  <main>
    <!-- HERO with Mood-to-Method #1 -->
    <section class="hero">
      <div class="container hero-grid">
        <div class="hero-copy">
          <h1>Small course-corrections that hold up under a busy life</h1>
          <p class="lead">Short, practical series and live events that make dependable habits more likely — outcomes, repeatable steps, and a clear next action.</p>

          <div class="mood-card">
            <label class="mood-label">How are you feeling today?</label>
            <div class="mood-options" data-target="#hero-method" data-cta=".hero-cta">
              <button class="mood" data-key="overwhelmed">Overwhelmed</button>
              <button class="mood" data-key="stalled">Stalled</button>
              <button class="mood" data-key="wired">Wired</button>
            </div>
            <p id="hero-method" class="method-suggestion">Choose a state to see a recommended approach.</p>
            <a class="hero-cta primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>

        </div>
        <div class="hero-visual">
          <svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
            <defs>
              <linearGradient id="g1" x1="0" x2="1">
                <stop offset="0" stop-color="#a8e6cf" />
                <stop offset="1" stop-color="#dcedc1" />
              </linearGradient>
            </defs>
            <rect x="10" y="10" width="180" height="180" rx="20" fill="url(#g1)" />
            <g fill="#ffffff" opacity="0.06">
              <circle cx="60" cy="60" r="24" />
              <circle cx="140" cy="120" r="18" />
              <rect x="50" y="120" width="40" height="10" rx="5" />
            </g>
          </svg>
        </div>
      </div>
    </section>

    <!-- STORY: unique order for index (story before framework) -->
    <section class="story">
      <div class="container">
        <div class="story-inner">
          <h2>Why short series work better than vague intentions</h2>
          <p>We build outcomes by choosing one habit, designing a tiny routine, and testing it across several weekly touchpoints. Events are structured so you leave with a working micro-plan, not just notes.</p>
          <ul>
            <li><strong>Outcome-focused:</strong> each series ends with a clear practice you can repeat.</li>
            <li><strong>Habits by design:</strong> micro-steps that fit your real calendar.</li>
            <li><strong>Practice templates:</strong> easy frameworks to reuse when life changes.</li>
          </ul>
        </div>
      </div>
    </section>

    <!-- FRAMEWORK & Mood-to-Method #2 -->
    <section class="framework">
      <div class="container">
        <h3>Our approach (a simple 3-part loop)</h3>
        <div class="framework-grid">
          <div class="frame">
            <h4>Pick one outcome</h4>
            <p>Focus on a single, high-leverage change you can test for two weeks.</p>
          </div>
          <div class="frame">
            <h4>Design a 5-minute ritual</h4>
            <p>Tiny, repeatable steps beat big plans that never start.</p>
          </div>
          <div class="frame">
            <h4>Schedule check-ins</h4>
            <p>Short live sessions hold momentum and course-correct quickly.</p>
          </div>
        </div>

        <div class="mood-card slim">
          <label class="mood-label">Pick your current state</label>
          <div class="mood-options" data-target="#framework-method" data-cta=".framework-cta">
            <button class="mood" data-key="overwhelmed">Overwhelmed</button>
            <button class="mood" data-key="stalled">Stalled</button>
            <button class="mood" data-key="wired">Wired</button>
          </div>
          <p id="framework-method" class="method-suggestion">A short prompt will appear here with a next step.</p>
          <a class="framework-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>

      </div>
    </section>

    <!-- OFFERS: Events series -->
    <section class="offers">
      <div class="container">
        <h3>Upcoming focused series</h3>
        <div class="offers-grid">
          <article class="offer">
            <h4>Rhythm Reset — 3-week series</h4>
            <p>Reclaim a dependable morning and evening pattern that sustains your energy across the week.</p>
            <p class="muted">Includes two live workshops + 3 group check-ins</p>
            <a href="programs.html#rhythm" class="secondary">See dates</a>
          </article>
          <article class="offer">
            <h4>Focus Capsule — 4 sessions</h4>
            <p>Simple practices to build clearer work blocks and fewer distractions.</p>
            <p class="muted">Practical templates and short in-between assignments</p>
            <a href="programs.html#focus" class="secondary">See dates</a>
          </article>
          <article class="offer">
            <h4>Recovery Arc — single intensive</h4>
            <p>A focused weekend to reframe rest, reset your expectations, and return with a realistic plan.</p>
            <p class="muted">Includes one 60-minute follow-up</p>
            <a href="programs.html#recovery" class="secondary">See dates</a>
          </article>
        </div>
      </div>
    </section>

    <!-- PRICING: includes comparator -->
    <section class="pricing">
      <div class="container">
        <h3>Transparent rates</h3>
        <p class="muted">Pick billing that fits your rhythm — monthly or a one-time package for a full series.</p>

        <div class="comparator">
          <div class="toggle">
            <span>Monthly</span>
            <label class="switch">
              <input type="checkbox" id="priceToggle" aria-label="Toggle pricing" />
              <span class="slider"></span>
            </label>
            <span>Package</span>
          </div>

          <div class="plans" id="plans">
            <div class="plan">
              <h4>Starter</h4>
              <div class="price" data-month="49" data-package="420">$<span>49</span></div>
              <p class="muted">For testing a single habit across a short series</p>
            </div>
            <div class="plan popular">
              <h4>Core</h4>
              <div class="price" data-month="149" data-package="1200">$<span>149</span></div>
              <p class="muted">Our most common path for building lasting routines</p>
            </div>
            <div class="plan">
              <h4>Deep</h4>
              <div class="price" data-month="299" data-package="2400">$<span>299</span></div>
              <p class="muted">For a multi-week overhaul with one-to-one support</p>
            </div>
          </div>
        </div>

        <p class="price-note">Prices animate when you switch billing types. Packages show the total offer price.</p>
      </div>
    </section>

    <!-- TESTIMONIALS -->
    <section class="testimonials">
      <div class="container">
        <h3>Voices</h3>
        <div class="t-grid">
          <blockquote>
            <p>After one series I had a morning habit that stuck. The weekly check-ins made it real.</p>
            <cite>— A client, {{CITY}}, {{STATE}}</cite>
          </blockquote>
          <blockquote>
            <p>Short, practical, and actually useful for a hectic schedule.</p>
            <cite>— Workshop attendee</cite>
          </blockquote>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta-brick">
      <div class="container">
        <h4>Ready for a short, practical plan?</h4>
        <p>Book a quick call to map one small routine you can start this week.</p>
        <a class="primary big" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="container footer-row">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <div class="muted">Events & short series — outcomes and repeatable practices</div>
      </div>
      <div class="contact">
        <a href="tel:{{PHONE}}">{{PHONE}}</a>
        <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
