{"path":"assets/css/styles.css","content":"/* Core layout and playful but bold visuals */
:root{
  --bg:#ffffff;
  --muted:#6b6b6b;
  --accent:#19a974;
  --accent-2:#7dd3c6;
  --dark:#0f1720;
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; margin:0;color:var(--dark);background:linear-gradient(180deg,#fbfdfb 0%, #ffffff 100%)}
.container{max-width:var(--max-width);margin:0 auto;padding:28px}
.header-row{display:flex;align-items:center;gap:16px}
.brand{font-weight:700;color:var(--dark);text-decoration:none;font-size:1.05rem}
.nav ul{list-style:none;margin:0;padding:0;display:flex;gap:12px}
.nav a{color:var(--dark);text-decoration:none;padding:8px 6px;border-radius:6px}
.nav a:hover{background:#f0fbf6}
.cta{margin-left:auto;background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px;text-decoration:none}
.nav-toggle{display:none;background:transparent;border:0;font-size:1.2rem}
.pattern{position:absolute;right:0;top:0;width:240px;height:80px;opacity:0.6}
.hero{padding:36px 0;background:linear-gradient(180deg,#f6fff7 0%, #ffffff 60%)}
.hero-grid{display:grid;grid-template-columns:1fr 320px;gap:24px;align-items:center}
.hero-copy h1{font-size:1.8rem;margin:0 0 8px}
.lead{color:var(--muted);margin:0 0 18px}
.hero-visual svg{width:100%;max-width:320px}
.mood-card{background:#fff;border-radius:12px;padding:14px;box-shadow:0 8px 24px rgba(12,15,12,0.06);max-width:520px}
.mood-card.slim{margin-top:18px}
.mood-options{display:flex;gap:10px;margin:8px 0}
.mood{background:#f7fffb;border:1px solid #eef7f2;padding:8px 10px;border-radius:8px;cursor:pointer}
.mood:hover{background:var(--accent-2)}
.method-suggestion{margin:10px 0 0;color:var(--muted)}
.primary{background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;text-decoration:none;display:inline-block}
.primary.big{padding:14px 20px;font-weight:700}
.framework{padding:26px 0}
.framework-grid{display:flex;gap:12px}
.frame{background:#fff;padding:14px;border-radius:10px;box-shadow:0 6px 18px rgba(10,12,10,0.04);flex:1}
.offers{padding:18px 0}
.offers-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.offer{background:#fff;padding:14px;border-radius:10px}
.offer .muted{color:var(--muted);font-size:0.9rem}
.secondary{color:var(--accent);text-decoration:none}
.pricing{padding:22px 0;background:linear-gradient(180deg,#ffffff 0%, #f6fffb 100%)}
.comparator{background:#fff;padding:18px;border-radius:12px;box-shadow:0 8px 20px rgba(12,15,12,0.03)}
.toggle{display:flex;align-items:center;gap:10px;justify-content:center;margin-bottom:16px}
.switch{position:relative;display:inline-block;width:44px;height:24px}
.switch input{opacity:0;width:0;height:0}
.slider{position:absolute;cursor:pointer;top:0;left:0;right:0;bottom:0;background:#e6f6ef;border-radius:24px}
.slider:before{position:absolute;content:"";height:18px;width:18px;left:3px;top:3px;background:white;border-radius:50%;transition:0.2s}
.switch input:checked + .slider{background:linear-gradient(90deg,var(--accent),var(--accent-2))}
.switch input:checked + .slider:before{transform:translateX(20px)}
.plans{display:flex;gap:12px;justify-content:space-between}
.plan{flex:1;padding:12px;border-radius:10px;background:#fbfff9;text-align:center}
.plan.popular{box-shadow:0 12px 30px rgba(25,169,116,0.08);transform:translateY(-6px)}
.price{font-weight:700;font-size:1.6rem;margin:8px 0}
.price-note{color:var(--muted);font-size:0.9rem;margin-top:10px}
.testimonials{padding:18px 0}
.t-grid{display:flex;gap:12px}
blockquote{background:#fff;padding:14px;border-radius:10px;flex:1}
.site-footer{border-top:1px solid #eef3ee;padding:18px 0;margin-top:32px}
.footer-row{display:flex;justify-content:space-between;align-items:center}
.muted{color:var(--muted)}
@media(max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .offers-grid{grid-template-columns:1fr}
  .plans{flex-direction:column}
  .nav{display:none}
  .nav-toggle{display:block;margin-left:auto}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Nav toggle for small screens
  var navToggle = document.querySelector('.nav-toggle');
  var nav = document.querySelector('.nav');
  if(navToggle){
    navToggle.addEventListener('click', function(){
      if(nav.style.display === 'block') nav.style.display = '';
      else nav.style.display = 'block';
    });
  }

  // Mood-to-Method logic (used twice on page)
  var moodMap = {
    overwhelmed: {
      title: 'Shortening decisions: a 3-step pause',
      detail: 'Anchor one 2-minute cue, follow with a single tiny action, and log one quick note. Start for 5 days.',
      cta: 'Book a 15-min pause call',
      url: 'book.html?mood=overwhelmed'
    },
    stalled: {
      title: 'Restart micro momentum',
      detail: 'Choose one visible win (5 mins), practice it twice this week, and schedule a 20-min review.',
      cta: 'Reserve a momentum spot',
      url: 'book.html?mood=stalled'
    },
    wired: {
      title: 'Wind-down rituals that work',
      detail: 'Create a 4-step evening anchor and test it for 10 nights; we’ll refine the order together.',
      cta: 'Start a wind-down plan',
      url: 'book.html?mood=wired'
    }
  };

  function bindMoodOptions(root){
    var options = root.querySelectorAll('.mood');
    var targetSelector = root.getAttribute('data-target');
    var ctaSelector = root.getAttribute('data-cta');
    var target = targetSelector ? document.querySelector(targetSelector) : null;
    var ctaEl = ctaSelector ? document.querySelector(ctaSelector) : null;

    options.forEach(function(btn){
      btn.addEventListener('click', function(){
        var key = btn.getAttribute('data-key');
        var map = moodMap[key];
        if(!map) return;
        // update suggestion
        if(target){
          target.classList.add('fade');
          setTimeout(function(){
            target.innerHTML = '<strong>'+map.title+'</strong> — '+map.detail;
            target.classList.remove('fade');
          },150);
        }
        // update CTA button text and link if available
        if(ctaEl){
          ctaEl.dataset.original = ctaEl.textContent;
          ctaEl.textContent = map.cta;
          ctaEl.setAttribute('href', map.url);
        }
      });
    });
  }

  // Initialize both mood option groups
  var moodGroups = document.querySelectorAll('.mood-options');
  moodGroups.forEach(function(group){ bindMoodOptions(group); });

  // Pricing comparator with animated numbers
  var toggle = document.getElementById('priceToggle');
  var planEls = document.querySelectorAll('.price');
  var animDuration = 400; // ms

  function animateNumber(el, start, end, duration){
    var startTime = null;
    var span = el.querySelector('span');
    if(!span) return;
    function step(ts){
      if(!startTime) startTime = ts;
      var progress = Math.min((ts - startTime)/duration, 1);
      var value = Math.round(start + (end - start) * progress);
      span.textContent = value.toString();
      if(progress < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }

  function setPrices(usePackage){
    planEls.forEach(function(el){
      var month = parseInt(el.getAttribute('data-month'),10)||0;
      var pack = parseInt(el.getAttribute('data-package'),10)||0;
      var from = parseInt(el.querySelector('span').textContent,10)||0;
      var to = usePackage ? pack : month;
      animateNumber(el, from, to, animDuration);
    });
  }

  if(toggle){
    toggle.addEventListener('change', function(){
      setPrices(toggle.checked);
    });
  }

  // Initialize prices to monthly (ensures correct span values)
  document.addEventListener('DOMContentLoaded', function(){
    setPrices(false);
  });

})();
"} 
